import{_ as d,o as a,c as e,ai as o}from"./chunks/framework.C33Uq6m-.js";const g=JSON.parse('{"title":"模型","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/models.md","filePath":"zh/guide/models.md"}'),r={name:"zh/guide/models.md"};function l(s,t,c,n,i,h){return a(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="模型" tabindex="-1">模型 <a class="header-anchor" href="#模型" aria-label="Permalink to &quot;模型&quot;">​</a></h1><p>模型页是一个浏览器，用于查看本地 Ollama 实例中安装的所有模型，并提供详细的元数据与能力检测。</p><p><strong>侧边栏位置：</strong> 模型 <strong>路由：</strong> <code>/settings?tab=models</code></p><h2 id="界面概览" tabindex="-1">界面概览 <a class="header-anchor" href="#界面概览" aria-label="Permalink to &quot;界面概览&quot;">​</a></h2><p>模型页（通过 设置 &gt; 模型 标签页进入）为每个已安装的模型显示一张卡片或一行条目，关键信息一目了然。</p><h2 id="模型详情" tabindex="-1">模型详情 <a class="header-anchor" href="#模型详情" aria-label="Permalink to &quot;模型详情&quot;">​</a></h2><p>每张模型卡片显示：</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><strong>名称</strong></td><td>模型标识（例如 <code>llama3.2:latest</code>）</td></tr><tr><td><strong>参数量</strong></td><td>参数数量（例如 3B、7B、70B）</td></tr><tr><td><strong>量化等级</strong></td><td>压缩程度（例如 Q4_0、Q8_0、F16）</td></tr><tr><td><strong>系列</strong></td><td>模型系列（例如 llama、mistral、gemma）</td></tr><tr><td><strong>格式</strong></td><td>模型格式（例如 gguf）</td></tr></tbody></table><h2 id="结构示意图" tabindex="-1">结构示意图 <a class="header-anchor" href="#结构示意图" aria-label="Permalink to &quot;结构示意图&quot;">​</a></h2><p>点击某个模型，可以看到一张结构示意图，展示模型的内部构造 —— 层数、注意力头数、嵌入维度等。这些信息解析自 Ollama 的模型元数据。</p><h2 id="能力检测" tabindex="-1">能力检测 <a class="header-anchor" href="#能力检测" aria-label="Permalink to &quot;能力检测&quot;">​</a></h2><p>LLMxRay 会自动检测每个模型能做什么。能力信息是<strong>实时从 Ollama 读取的</strong>，因此新发布的模型无需 LLMxRay 更新即可正常工作。当模型自己没有报告时，LLMxRay 会退回到基于名称的模式匹配。</p><p>从 <strong>Ollama 0.32</strong> 起，模型列表接口（<code>/api/tags</code>）会直接报告每个模型的能力、上下文长度和嵌入宽度。LLMxRay 以此为主要来源，因此能力图标和模型筛选在列表加载的那一刻就是正确的，而不必等待逐个模型的 <code>/api/show</code> 往返。<code>/api/show</code> 仍会在后台运行，用参数、模板和架构元数据丰富缓存。</p><table tabindex="0"><thead><tr><th>能力</th><th>如何检测</th><th>界面上的效果</th></tr></thead><tbody><tr><td><strong>推理</strong></td><td>Ollama <code>capabilities</code>，否则用名称模式（<code>deepseek-r1</code>、<code>qwq</code>、<code>gpt-oss</code>、<code>magistral</code>、<code>nemotron</code>、<code>qwen3.x</code>、<code>muse-glimmer</code>、<code>glm-*</code>、<code>kimi-k*</code> 等）</td><td>启用对话诊断中的推理标签页</td></tr><tr><td><strong>视觉</strong></td><td>Ollama <code>capabilities</code>，否则用名称模式（<code>llava</code>、<code>*-vl</code>、<code>moondream</code>、<code>gemma3</code>、Llama-vision 等）</td><td>启用对话中的图片附件</td></tr><tr><td><strong>嵌入</strong></td><td>Ollama <code>capabilities</code>，否则用模型系列或名称</td><td>出现在嵌入页和知识库的模型选择器中</td></tr><tr><td><strong>工具调用</strong></td><td>Ollama <code>capabilities</code></td><td>启用对话中的工具调用</td></tr></tbody></table><p>由于能力信息直接来自 Ollama，LLMxRay 会自动跟上新的模型系列。被报告出来的能力集合被视为权威 —— 如果守护进程列出了某个模型的能力但其中<em>没有</em> <code>thinking</code>，LLMxRay 会相信它，而不是根据名称去猜。名称模式只在模型完全没有报告任何能力时才生效。</p><p>只支持嵌入的模型会被自动从对话模型选择器中过滤掉。</p><h2 id="推理强度" tabindex="-1">推理强度 <a class="header-anchor" href="#推理强度" aria-label="Permalink to &quot;推理强度&quot;">​</a></h2><p>对于具备推理能力的模型，对话诊断页会暴露 Ollama 的 <code>think</code> 参数：</p><table tabindex="0"><thead><tr><th>设置</th><th>发送为</th><th>含义</th></tr></thead><tbody><tr><td><strong>关闭</strong></td><td><em>（不发送）</em></td><td>不进行内部推理</td></tr><tr><td><strong>开启</strong></td><td><code>true</code></td><td>启用推理；由模型自行决定投入多少</td></tr><tr><td><strong>低 / 中 / 高</strong></td><td><code>&quot;low&quot;</code> / <code>&quot;medium&quot;</code> / <code>&quot;high&quot;</code></td><td>明确指定推理预算</td></tr><tr><td><strong>最大</strong></td><td><code>&quot;max&quot;</code></td><td>最大推理预算</td></tr></tbody></table><p>不支持分级强度的模型，会把任何级别都当作「开启推理」处理。</p><h2 id="嵌入维度" tabindex="-1">嵌入维度 <a class="header-anchor" href="#嵌入维度" aria-label="Permalink to &quot;嵌入维度&quot;">​</a></h2><p>嵌入页可以通过 Ollama 的 <code>dimensions</code> 参数请求更窄的输出向量（Matryoshka 截断）。留空则使用模型的原生宽度 —— 该宽度会作为输入框的占位提示，读取自模型列表。未针对 Matryoshka 截断训练的模型，无论如何都会返回原生宽度。</p><h2 id="模型目录" tabindex="-1">模型目录 <a class="header-anchor" href="#模型目录" aria-label="Permalink to &quot;模型目录&quot;">​</a></h2><p>目录提供一份经过整理的可用模型视图，附带对比表格，帮助你为自己的使用场景挑选合适的模型。</p><h2 id="小贴士" tabindex="-1">小贴士 <a class="header-anchor" href="#小贴士" aria-label="Permalink to &quot;小贴士&quot;">​</a></h2><ul><li><strong>量化的取舍</strong> —— 更低的量化等级（Q4）占用更少内存，但质量略有下降。Q8 和 F16 质量更高，但需要更多内存。</li><li><strong>拉取更多模型</strong>可在终端中进行：<code>ollama pull &lt;模型名&gt;</code></li><li>能力检测会自动调整整个界面 —— 你不需要手动配置任何东西。</li></ul>',26)])])}const p=d(r,[["render",l]]);export{g as __pageData,p as default};
